import { html } from "../../../../html.js";
import { useState } from "/prototype/vendor/preact-hooks.js";
import { Dialog, Icon } from "../../ui/index.js";
import PageVariants from "../../ui/PageVariants.js";

const sections=[['policy','Policy','shield-check'],['access','Access','users'],['keys','Keys','key-round'],['signals','Signals','bell'],['governance','Governance','scroll-text'],['system','System','server']];
const audit=[['Policy changed','Production writes now require approval','N. Rivera','02:18'],['Passkey enrolled','MacBook Pro • platform-admin','A. Chen','Yesterday'],['GitHub scope reviewed','contents:write retained for 3 repositories','System','Yesterday'],['Fleet pause cleared','Paused 14 agents for 8 minutes','N. Rivera','Oct 21']];
const Toggle=({on,setOn,label,detail})=>html`<label class="p-admin-toggle"><button role="switch" aria-checked=${on} class=${on?'on':''} onClick=${()=>setOn(!on)}><i></i></button><span><b>${label}</b><small>${detail}</small></span></label>`;
const Toast=({text})=>text&&html`<div class="p-admin-toast" role="status">${text}</div>`;
function Header({title,kicker,children}){return html`<header class="p-admin-head"><div><p>${kicker}</p><h1>${title}</h1></div>${children}</header>`}
function Policy({data}){const [section,setSection]=useState('policy'),[preview,setPreview]=useState(false),[toast,setToast]=useState(''); const [paused,setPaused]=useState(false),[confirm,setConfirm]=useState(false); const notify=text=>{setToast(text);setTimeout(()=>setToast(''),2500)}; return html`<div class="p-admin-workbench"><aside class="p-admin-nav"><strong>Organization</strong>${sections.map(([id,label,icon])=>html`<button class=${section===id?'on':''} onClick=${()=>setSection(id)}><${Icon} name=${icon}/>${label}</button>`)}<div><small>Workspace</small><b>acme-platform</b><span><i></i> healthy</span></div></aside><section class="p-admin-main"><${Header} kicker="Control plane" title=${section==='policy'?'Organization policy':'Settings — '+sections.find(x=>x[0]===section)[1]}/><div class="p-admin-policy-toolbar"><div class="e-tabs"><button class=${!preview?'on':''} onClick=${()=>setPreview(false)}>Editor</button><button class=${preview?'on':''} onClick=${()=>setPreview(true)}>Effective policy</button></div><button class="p-admin-button" onClick=${()=>notify('Policy saved — applies to new runs')}>Save changes</button></div>${preview?html`<article class="p-admin-code"><small>Resolved policy • production</small><pre>approval: required
model: claude-sonnet
max_cost_per_run: $12.00
network: github, linear
retention_days: 30</pre><p>Inherited by 4 projects. Two project exceptions remain.</p></article>`:html`<div class="p-admin-editor"><article><div class="p-admin-card-title"><span><${Icon} name="shield-check"/></span><div><h2>Change boundaries</h2><p>Require a human before an agent makes consequential changes.</p></div></div><${Toggle} on=${true} setOn=${()=>notify('Approval rule updated')} label="Approval for protected branches" detail="Ask before merge, deploy, or changing secrets"/><${Toggle} on=${true} setOn=${()=>notify('Scope rule updated')} label="Stay inside assigned repositories" detail="Block cross-project writes unless explicitly delegated"/></article><article><div class="p-admin-card-title"><span><${Icon} name="bot"/></span><div><h2>Agent capability</h2><p>Default guardrails for all new agents.</p></div></div><div class="p-admin-fields"><label>Model allowlist<select><option>Claude Sonnet</option><option>GPT-4.1</option></select></label><label>Tool allowlist<select><option>GitHub + Linear + shell</option><option>GitHub only</option></select></label><label>Run budget<input value="$12.00" readOnly/></label></div></article><article class="p-admin-pause"><div><b>Global fleet pause</b><small>Immediately stop starting new work. Running jobs can reach a safe checkpoint.</small></div><button class="p-admin-danger" onClick=${()=>setConfirm(true)}>${paused?'Resume fleet':'Pause fleet'}</button></article></div>`}</section><aside class="p-admin-aside"><h3>Policy health</h3><div class="p-admin-score">92<span>/100</span></div><p>Strong baseline. Review two exceptions before the next release.</p><button onClick=${()=>setSection('governance')}>Review exceptions <${Icon} name="arrow-up-right"/></button><hr/><h3>Connected</h3>${data.connectors.map(c=>html`<div class="p-admin-connector"><span class=${c.status==='ok'?'good':''}></span><b>${c.id}</b><small>${c.status}</small></div>`)}</aside>${confirm&&html`<${Dialog} onClose=${()=>setConfirm(false)}><div class="p-admin-dialog"><${Icon} name="triangle-alert"/><h2>Pause the entire fleet?</h2><p>New work will not start across all organizations until someone resumes it.</p><div><button onClick=${()=>setConfirm(false)}>Cancel</button><button class="p-admin-danger" onClick=${()=>{setPaused(!paused);setConfirm(false);notify(paused?'Fleet resumed':'Fleet paused safely')}}>${paused?'Resume fleet':'Pause fleet'}</button></div></div></${Dialog}>`}<${Toast} text=${toast}/></div>`}
function Audit(){const [filter,setFilter]=useState('All activity'),[open,setOpen]=useState(null);return html`<div class="p-admin-audit"><${Header} kicker="Governance" title="Audit explorer"><button class="p-admin-button">Export log</button></${Header}><div class="p-admin-audit-layout"><aside><b>Filters</b>${['All activity','Policy','Access','Connectors','Agent actions'].map(x=>html`<button class=${filter===x?'on':''} onClick=${()=>setFilter(x)}>${x}<span>${x==='All activity'?'248':''}</span></button>`)}<hr/><small>TIME RANGE</small><button class="on">Last 30 days</button><button>Custom range</button></aside><section><div class="p-admin-search"><${Icon} name="search"/><input aria-label="Search audit log" placeholder="Search actor, action, or resource"/><button>⌘ K</button></div><div class="p-admin-timeline">${audit.map((x,i)=>html`<button class="p-admin-event" onClick=${()=>setOpen(i)}><span class=${i===0?'teal':''}><${Icon} name=${i===0?'shield-check':'circle-dot'}/></span><div><b>${x[0]}</b><p>${x[1]}</p><small>${x[2]} · ${x[3]}</small></div><${Icon} name="chevron-right"/></button>`)}</div></section>${open!==null&&html`<aside class="p-admin-detail"><button aria-label="Close detail" onClick=${()=>setOpen(null)}>×</button><small>EVENT DETAIL</small><h2>${audit[open][0]}</h2><dl><dt>Actor</dt><dd>${audit[open][2]}</dd><dt>Time</dt><dd>${audit[open][3]}</dd><dt>Source</dt><dd>Console · 127.0.0.1</dd></dl><pre>{"requestId":"evt_84k2","result":"success"}</pre></aside>`}</div></div>`}
function Controls({data}){const [toast,setToast]=useState('');const [retention,setRetention]=useState('30 days');return html`<div class="p-admin-controls"><${Header} kicker="Operations" title="Fleet controls"><div class="p-admin-live"><i></i> ${data.agentsList.length} agents online</div></${Header}><div class="p-admin-control-grid"><article class="p-admin-hero-card"><small>SPEND THIS MONTH</small><h2>$4.82 <span>/ $8.00 limit</span></h2><div class="p-admin-meter"><i></i></div><p>60% of the organization budget used. Forecast: $6.30.</p><button onClick=${()=>setToast('Budget editor opened')}>Edit budget</button></article><article><h3>Identity and access</h3><p>12 members · 4 admins · passkeys enforced</p><div class="p-admin-avatars"><i>NR</i><i>AC</i><i>JP</i><b>+9</b></div><button onClick=${()=>setToast('Member directory opened')}>Manage members</button></article><article><h3>Notifications</h3><p>Web Push enabled for approvals and fleet incidents.</p><${Toggle} on=${true} setOn=${()=>setToast('Notification preference saved')} label="Critical alerts" detail="Immediate delivery"/></article><article><h3>Data lifecycle</h3><p>Transcripts and tool results are automatically pruned.</p><label class="p-admin-select">Retention<select value=${retention} onChange=${e=>setRetention(e.target.value)}><option>7 days</option><option>30 days</option><option>90 days</option></select></label></article><article class="p-admin-wide"><div><h3>API keys and integrations</h3><p>3 scoped tokens · GitHub, Linear, and Slack connected</p></div><div><button onClick=${()=>setToast('Token inventory opened')}>View tokens</button><button class="p-admin-button" onClick=${()=>setToast('Integration catalog opened')}>Add integration</button></div></article><article class="p-admin-wide p-admin-danger-zone"><div><h3>Danger zone</h3><p>Transfer ownership, revoke all device sessions, or permanently delete this organization.</p></div><button class="p-admin-danger" onClick=${()=>setToast('Destructive actions require confirmation')}>Manage danger zone</button></article></div><footer class="p-admin-about">Durable Console <b>v0.0.0</b><span>•</span> Policy engine 3.4 <a>Release notes</a></footer><${Toast} text=${toast}/></div>`}
export default function AdminPage({data}){return html`<main class="e-page p-admin-page"><${PageVariants} variants=${[{key:'1',name:'Policy studio',render:()=>html`<${Policy} data=${data}/>`},{key:'2',name:'Audit trail',render:()=>html`<${Audit}/>`},{key:'3',name:'Control center',render:()=>html`<${Controls} data=${data}/>`}]}/></main>`;}
